	private void EncountUpdate(float deltatime) {
        switch (_encountUpdateType)
        {
            case EncountUpdateType.CallEffect:
            {
                Application.backgroundLoadingPriority = ThreadPriority.High;
                _encountUpdateType = EncountUpdateType.EndWait;

                if (_encEffctController == null)
                {
                    if (_encountFadeType == EncountFadeType.Normal)
                    {
                        GameManager.GetAttribute(EntityManager.activeFieldPlayer.gridPosition, out int code, out int stop, false);
                        var attributeTable = GameManager.GetAttributeTable(code);
                        PreLoadEncEffect(string.IsNullOrEmpty(attributeTable.FieldEncount) ? "nagakusa01" : attributeTable.FieldEncount);
                    }
                    else if (_encountFadeType == EncountFadeType.Trainer)
                    {
                        if (_btl_trainerID1 == TrainerID.NONE)
                        {
                            _encountUpdateType = EncountUpdateType.End;
                        }
                        else
                        {
                            var trainerType1 = DataManager.TrainerTable.TrainerData[(int)_btl_trainerID1].TypeID;
                            if (_btl_trainerID2 != TrainerID.NONE)
                            {
                                var trainerType2 = DataManager.TrainerTable.TrainerData[(int)_btl_trainerID2].TypeID;
                                PreLoadEncEffect(TrainerWork.IsTokushuEncount(trainerType1) || TrainerWork.IsTokushuEncount(trainerType2) ? "elagula/01" : "trainer_duble01");
                            }
                            else
                            {
                                // @0179b090–0179b21c: an unrolled 6-slot loop (unsigned compares) over the party levels.
                                var party = PlayerWork.playerParty;
                                uint partyMaxLevel = 0;
                                for (uint i = 0; i < 6; i++)
                                {
                                    var pp = party.GetMemberPointer(i);
                                    if (pp != null && pp.GetLevel() > partyMaxLevel)
                                        partyMaxLevel = pp.GetLevel();
                                }

                                // @0179b23c–0179b560: the TrainerPoke row is re-read from DataManager for every test.
                                byte trainerMaxLevel = 0;
                                if (trainerMaxLevel < DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P1Level)
                                    trainerMaxLevel = DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P1Level;
                                if (trainerMaxLevel < DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P2Level)
                                    trainerMaxLevel = DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P2Level;
                                if (trainerMaxLevel < DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P3Level)
                                    trainerMaxLevel = DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P3Level;
                                if (trainerMaxLevel < DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P4Level)
                                    trainerMaxLevel = DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P4Level;
                                if (trainerMaxLevel < DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P5Level)
                                    trainerMaxLevel = DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P5Level;
                                if (trainerMaxLevel < DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P6Level)
                                    trainerMaxLevel = DataManager.TrainerTable.TrainerPoke[(int)_btl_trainerID1].P6Level;

                                string effectName = partyMaxLevel < trainerMaxLevel ?
                                    DataManager.TrainerTable.TrainerType[(int)trainerType1].FieldEncount[0] :
                                    DataManager.TrainerTable.TrainerType[(int)trainerType1].FieldEncount[1];

                                GameManager.GetAttribute(EntityManager.activeFieldPlayer.gridPosition, out int code, out int stop, false);
                                var attributeTable = GameManager.GetAttributeTable(code);

                                string folder = "field";
                                if (TrainerWork.IsTokushuEncount(trainerType1))
                                    folder = "elagula";
                                else if (AttributeID.MATR_IsWater(attributeTable.Code))
                                    folder = "sea";
                                else if (ZoneData.MapType == MapType.MAPTYPE_CAVE || ZoneData.MapType == MapType.MAPTYPE_UNDERGROUND)
                                    folder = "dungeon";

                                PreLoadEncEffect(folder + "/" + effectName);
                            }
                        }
                    }
                }

                BattleConnector.PrepareOperationStatic();
                break;
            }

            case EncountUpdateType.EndWait:
                if (_encEffctController.PlayState == EncEffectSequenceController.ePlayState.Finish)
                {
                    // @0179af00–0179af54: FieldCamera offset / offsetAngle auto-property setters inlined (+0x78 / +0x84).
                    GameManager.fieldCamera.offset = Vector3.zero;
                    GameManager.fieldCamera.offsetAngle = Vector3.zero;
                    _encEffctController.Release();
                    _encEffctController = null;
                    PlayerWork.isEncount = true;
                    _encountUpdateType = EncountUpdateType.End;
                    Fader.fadeMode = Fader.FadeMode.Color;
                }
                else if (_encEffctController.PlayState == EncEffectSequenceController.ePlayState.PlayStandBy)
                {
                    // SetWwiseEvent(uint) inlined twice (flag 0x4cbb309 @0179ad80 / @0179ae6c).
                    SetWwiseEvent(AK.EVENTS.EV_END);
                    var battleBgm = PlayerWork.battleSetupParam.btlEffComponent.battleBgm;
                    SetWwiseEvent(AkSoundEngine.GetIDFromString(string.IsNullOrEmpty(battleBgm) ? "BA001" : battleBgm));
                    _encEffctController.Play();
                }
                break;

            case EncountUpdateType.End:
                Application.backgroundLoadingPriority = ThreadPriority.BelowNormal;
                break;
        }
    }
	public void PreLoadEncEffect(string assetname) {
        if (_encEffctController != null)
        {
            _encEffctController.Release();
            _encEffctController = null;
        }

        _encEffctController = new EncEffectSequenceController("encseq/" + assetname, this);
    }
	public uint GetNowBgmState() {
        // @0179c830: `_nowEventId` get / set inlined (flags 0x4cbb2f3 / 0x4cbb2f4).
        if (_nowEventId != 0)
