	private bool CheckEncount() {
        if (UIManager.IsFieldOpenMenu())
            return false;

        GameManager.GetAttribute(EntityManager.activeFieldPlayer.gridPosition, out int code, out int stop, false);
        var attributeTable = GameManager.GetAttributeTable(code);
        if (!attributeTable.Encount)
        {
            _encountAttriLog = false;
            return false;
        }

#if PC_UNLOCKED_FPS
        if (PcPlatform.PcFrameClock.Ticks == 0 || (EntityManager.activeFieldPlayer.oldMoveVector.x == 0.0f && EntityManager.activeFieldPlayer.oldMoveVector.z == 0.0f))
#else
        if (EntityManager.activeFieldPlayer.oldMoveVector.x == 0.0f && EntityManager.activeFieldPlayer.oldMoveVector.z == 0.0f)
#endif
            return false;

        var attributeEx = GameManager.GetAttributeEx(EntityManager.activeFieldPlayer.gridPosition, EntityManager.activeFieldPlayer.Height, false);

        if (PlayerWork.WalkEncountCount <= _oldEncountWalkCount)
            _oldEncountWalkCount = PlayerWork.WalkEncountCount;

        // @0179d8e0–0179d92c: both terms evaluated (`cset` + `eor` + `orr`), the attribute log updated before the check.
        bool isSameWalkCount = _oldEncountWalkCount == PlayerWork.WalkEncountCount;
        bool isChangeAttribute = _encountAttriLog != attributeTable.Encount;
        _encountAttriLog = attributeTable.Encount;

        var result = FieldEncount.FieldEncount_Check(EntityManager.activeFieldPlayer, isSameWalkCount | isChangeAttribute);
        _oldEncountWalkCount = PlayerWork.WalkEncountCount;
        if (result == null)
            return false;

        PlayReportManager.StartWildBattle(PlayReportManager.eCaptureType.Wild);
        // @0179d9f8–0179da04: battleBgm setter inlined (one store to btlEffComponent +0x10).
        PlayerWork.battleSetupParam.btlEffComponent.battleBgm = "";
        PlayerWork.MovePokemonIndex = -1;
        _oldEncountWalkCount = 0;
        PlayerWork.WalkEncountCount = 0;

        int btlBgIndex = AttributeID.MATR_IsWater(attributeTable.Code) ? 1 : 0;
        switch (result.Type)
        {
            case EncountResult.BtlType.Single:
            {
                ResultSetUpWildBattle(result, btlBgIndex, out PokeParty party, out int safariBall);
                ArenaID arenaID = GameManager.mapInfo[(int)PlayerWork.zoneID].BattleBg[btlBgIndex];
                GetLegendPokeEncountInfo(party.GetMemberPointer(0), out string encSeq, ref arenaID, out string bgm, out BattleSetupEffectId setupEffect);
                if (!string.IsNullOrEmpty(encSeq))
                    PreLoadEncEffect(encSeq);

                EncountTools.SetupBattleWild(PlayerWork.battleSetupParam, party, arenaID, attributeEx.AttributeEx, GetBatleWeather(), PlayerWork.IsFormSwim(),
                    false, TrainerID.NONE, false, safariBall, false, false, bgm, setupEffect, false);
                break;
            }

            case EncountResult.BtlType.Double:
            {
                // @0179dd60: no legend lookup; the setup param is fetched before mapInfo; the partner trainer is passed.
                ResultSetUpWildBattle(result, btlBgIndex, out PokeParty party, out int safariBall);
                EncountTools.SetupBattleWild(PlayerWork.battleSetupParam, party, GameManager.mapInfo[(int)PlayerWork.zoneID].BattleBg[btlBgIndex],
                    attributeEx.AttributeEx, GetBatleWeather(), PlayerWork.IsFormSwim(), false, result.Partner, false, safariBall, false, false, null, 0, false);
                break;
            }

            case EncountResult.BtlType.Safari:
            {
                ResultSetUpWildBattle(result, btlBgIndex, out PokeParty party, out int safariBall);
                EncountTools.SetupBattleWild(PlayerWork.battleSetupParam, party, GameManager.mapInfo[(int)PlayerWork.zoneID].BattleBg[btlBgIndex],
                    attributeEx.AttributeEx, GetBatleWeather(), PlayerWork.IsFormSwim(), false, TrainerID.NONE, false, safariBall, false, false, null, 0, false);
                break;
            }

            case EncountResult.BtlType.MovePoke:
            {
                var movePokeData = default(MV_POKE_DATA);
                EncountDataWork.GetMovePokeData(result.MP_SaveIndex, ref movePokeData);

                ushort sex;
                ushort seikaku;
                switch (result.HatudouTokusei)
                {
                    case TokuseiNo.SINKURO:
                        seikaku = result.FixSeikaku[0] == Seikaku.NUM ? (ushort)0xFFFF : (ushort)result.FixSeikaku[0];
                        sex = 0xFF;
                        break;

                    case TokuseiNo.MEROMEROBODHI:
                        sex = result.FixSex[0] > Sex.FEMALE ? (ushort)0xFF : (ushort)result.FixSex[0];
                        seikaku = 0xFFFF;
                        break;

                    default:
                        seikaku = 0xFFFF;
                        sex = 0xFF;
                        break;
                }

                var pp = EncountTools.CreateFixPokeParam(result.Enemy[0], (ushort)result.Level[0], movePokeData.Hp, sex, seikaku, (Sick)movePokeData.Sick, movePokeData.RndSeed, 3);

                int item1rate;
                switch (result.HatudouTokusei)
                {
                    case TokuseiNo.HUKUGAN:
                    case TokuseiNo.KYOUUN:
                        item1rate = 60;
                        break;

                    default:
                        item1rate = 50;
                        break;
                }
                EncountTools.SetWildPokemonItem(pp, UnityEngine.Random.Range(0, 100), item1rate, 20);

                PlayerWork.MovePokemonIndex = result.MP_SaveIndex;
                var party = new PokeParty();
                party.AddMember(pp);

                ArenaID arenaID = GameManager.mapInfo[(int)PlayerWork.zoneID].BattleBg[btlBgIndex];
                GetLegendPokeEncountInfo(party.GetMemberPointer(0), out string encSeq, ref arenaID, out string bgm, out BattleSetupEffectId setupEffect);
                if (!string.IsNullOrEmpty(encSeq))
                    PreLoadEncEffect(encSeq);

                EncountTools.SetupBattleWild(PlayerWork.battleSetupParam, party, arenaID, attributeEx.AttributeEx, GetBatleWeather(), PlayerWork.IsFormSwim(),
                    false, TrainerID.NONE, false, -1, false, false, bgm, setupEffect, false);
                break;
            }
        }

        // @0179e190: wandering Pokémon move on every encounter except a wandering-Pokémon one.
        if (result.Type != EncountResult.BtlType.MovePoke)
        {
            for (int i = 0; i < PlayerWork.Enc_SV_Data.MovePokeData.Length; i++)
            {
                if (RandomGroupWork.RandomValue(100) < DataManager.FieldCommonParam[(int)ParamIndx.MVPokeEncMoveRate].param)
                    EncountDataWork.MovePoke_RandomZone(i);
            }
        }

        EncountStart(EncountFadeType.Normal);
        return true;
    }
	private void ResultSetUpWildBattle(global::Dpr.Field.EncountResult result, int btlBgIndex, out global::Pml.PokeParty party, out int safariball) {
        // @0179ea44: rates chosen by two `csel` pairs (HUKUGAN 14 / KYOUUN 105 → 60 / 20, else 50 / 5); btlBgIndex is never read.
        int item1rate = 50;
        int item2rate = 5;
        switch (result.HatudouTokusei)
        {
            case TokuseiNo.HUKUGAN:
            case TokuseiNo.KYOUUN:
                item1rate = 60;
                item2rate = 20;
                break;
        }

        ushort formNo = GetFormNo(result.Enemy[0], result.karanaForm, result.annoForm);

        if (result.Type == EncountResult.BtlType.Double)
        {
            var sex = new ushort[2] { 0xFF, 0xFF };
            var seikaku = new ushort[2] { 0xFFFF, 0xFFFF };
            for (int i = 0; i < 2; i++)
            {
                if (result.HatudouTokusei == TokuseiNo.MEROMEROBODHI && result.FixSex[i] <= Sex.FEMALE)
                    sex[i] = (ushort)result.FixSex[i];

                if (result.HatudouTokusei == TokuseiNo.SINKURO && result.FixSeikaku[i] != Seikaku.NUM)
                    seikaku[i] = (ushort)result.FixSeikaku[i];
            }

            ushort formNo2 = GetFormNo(result.Enemy[1], result.karanaForm, result.annoForm);
            party = EncountTools.CreateSimpleParty(result.Enemy[0], result.Level[0], result.Enemy[1], result.Level[1], null,
                sex[0], seikaku[0], sex[1], seikaku[1], formNo, formNo2, 0);

            EncountTools.SetWildPokemonItem(party.GetMemberPointer(0), UnityEngine.Random.Range(0, 100), item1rate, item2rate);
            EncountTools.SetWildPokemonItem(party.GetMemberPointer(1), UnityEngine.Random.Range(0, 100), item1rate, item2rate);
        }
        else
        {
            ushort sex;
            ushort seikaku;
            switch (result.HatudouTokusei)
            {
                case TokuseiNo.SINKURO:
                    seikaku = result.FixSeikaku[0] == Seikaku.NUM ? (ushort)0xFFFF : (ushort)result.FixSeikaku[0];
                    sex = 0xFF;
                    break;

                case TokuseiNo.MEROMEROBODHI:
                    sex = result.FixSex[0] > Sex.FEMALE ? (ushort)0xFF : (ushort)result.FixSex[0];
                    seikaku = 0xFFFF;
                    break;

                default:
                    seikaku = 0xFFFF;
                    sex = 0xFF;
                    break;
            }

            byte talentVNum = SwayGrass.RensaTalent();
            party = EncountTools.CreateSimpleParty(result.Enemy[0], result.Level[0], MonsNo.NULL, 1, null, sex, seikaku, 0xFF, 0xFFFF, formNo, 0, talentVNum);

            if (result.IsRare)
                party.GetMemberPointer(0).SetRare();

            if (result.IsKakure)
                party.GetMemberPointer(0).SetTokusei3rd();

            EncountTools.SetWildPokemonItem(party.GetMemberPointer(0), UnityEngine.Random.Range(0, 100), item1rate, item2rate);
        }

        safariball = result.Type == EncountResult.BtlType.Safari ? PlayerWork.SafariBallNum : -1;
    }
	private ushort GetFormNo(global::Pml.MonsNo mons, int karana, int anno) {
        // @0179f5a8: `and #~1 ; cmp #0x1a6` = KARANAKUSI (422) / TORITODON (423).
        if (mons == MonsNo.KARANAKUSI || mons == MonsNo.TORITODON)
            return (ushort)(karana != 0 ? 1 : 0);

        if (mons != MonsNo.ANNOON)
            return 0;

        unnnoonFormList.Clear();
        if (anno < 0 || anno >= GameManager.fieldEncountTable.zui.Length)
            anno = 1;

        var form = GameManager.fieldEncountTable.zui[anno].form;
        for (int i = 0; i < form.Length; i++)
        {
            if (form[i])
                unnnoonFormList.Add(i);
        }

        return (ushort)unnnoonFormList[RandomGroupWork.RandomRange(0, unnnoonFormList.Count)];
    }
	public void EventWildBattle(global::Pml.MonsNo mons, int level, bool isCaptureDemo = false, bool isSymbol = false, bool isMitu = false, byte talentVNum = 0, bool isCantUseBall = false, int formNo = 0, bool tokusei3rd = false) {
        var firstPokemon = PlayerWork.playerParty.GetMemberPointer(0);
        ushort sex = 0xFF;
        ushort seikaku = 0xFFFF;
        if (!firstPokemon.IsEgg(EggCheckType.BOTH_EGG))
        {
            // @0179f8a8 / @0179f900: GetTokuseiNo is called once per test.
            if (firstPokemon.GetTokuseiNo() == TokuseiNo.MEROMEROBODHI)
            {
                if (RandomGroupWork.RandomValue(3) >= 1)
                {
                    switch (firstPokemon.GetSex())
                    {
                        case Sex.MALE:
                            sex = (ushort)Sex.FEMALE;
                            break;

                        case Sex.FEMALE:
                            sex = (ushort)Sex.MALE;
                            break;
                    }
                }
            }
            else if (firstPokemon.GetTokuseiNo() == TokuseiNo.SINKURO)
            {
                seikaku = (ushort)firstPokemon.GetSeikaku();
            }
        }

        var party = EncountTools.CreateSimpleParty(mons, level, MonsNo.NULL, 1, null, sex, seikaku, 0xFF, 0xFFFF, (ushort)formNo, 0, talentVNum);

        // @0179f85c: the member pointer is fetched before the tokusei3rd test.
        var enemy = party.GetMemberPointer(0);
        if (tokusei3rd)
            enemy.SetTokusei3rd();

        EventWildBattle(party, isCaptureDemo, isSymbol, isMitu, isCantUseBall);
    }
	public void EventWildBattle(global::Pml.PokeParty pokeParty, bool isCaptureDemo = false, bool isSymbol = false, bool isMitu = false, bool isCantUseBall = false) {
        GameManager.GetAttribute(EntityManager.activeFieldPlayer.gridPosition, out int code, out int stop, false);
        var attributeTable = GameManager.GetAttributeTable(code);
        var attributeEx = GameManager.GetAttributeEx(EntityManager.activeFieldPlayer.gridPosition, EntityManager.activeFieldPlayer.Height, false);
        int btlBgIndex = AttributeID.MATR_IsWater(attributeTable.Code) ? 1 : 0;

        ArenaID arenaID = GameManager.mapInfo[(int)PlayerWork.zoneID].BattleBg[btlBgIndex];
        GetLegendPokeEncountInfo(pokeParty.GetMemberPointer(0), out string encSeq, ref arenaID, out string bgm, out BattleSetupEffectId setupEffect);
        if (!string.IsNullOrEmpty(encSeq))
            PreLoadEncEffect(encSeq);

        if (!isCaptureDemo)
            PlayReportManager.StartWildBattle(PlayReportManager.eCaptureType.Wild);

        EncountTools.SetupBattleWild(PlayerWork.battleSetupParam, pokeParty, arenaID, attributeEx.AttributeEx, GetBatleWeather(), false, false, TrainerID.NONE,
            isCaptureDemo, -1, isSymbol, isMitu, bgm, setupEffect, isCantUseBall);
        EncountStart(EncountFadeType.Normal);
    }
