	public void CallEffect(global::EffectFieldID index, global::UnityEngine.Transform parent, global::UnityEngine.Vector3 ofs, global::UnityEngine.Vector3 rot, global::System.Action<global::Effect.EffectInstance> loadcallback = null, global::UnityEngine.Events.UnityAction<global::Effect.EffectInstance> eff_onFinished = null) {
        // @017a0240: `tbnz index, #31` — NONE (-1) and below are ignored.
        if (index <= EffectFieldID.NONE)
            return;

        Sequencer.Start(PlayEffect(index, parent, ofs, Quaternion.Euler(rot), loadcallback, eff_onFinished));
    }
	public void CallEffect(global::EffectFieldID index, global::UnityEngine.Transform parent, global::UnityEngine.Vector3 ofs, global::System.Action<global::Effect.EffectInstance> loadcallback = null, global::UnityEngine.Events.UnityAction<global::Effect.EffectInstance> eff_onFinished = null) {
