	public void CallEffect(global::EffectFieldID index, global::UnityEngine.Vector3 pos, global::System.Action<global::Effect.EffectInstance> loadcallback = null, global::UnityEngine.Events.UnityAction<global::Effect.EffectInstance> eff_onFinished = null) {
        if (index <= EffectFieldID.NONE)
            return;

        Sequencer.Start(PlayEffect(index, null, pos, Quaternion.identity, loadcallback, eff_onFinished));
    }
	private global::System.Collections.IEnumerator PlayEffect(global::EffectFieldID index, global::UnityEngine.Transform parent, global::UnityEngine.Vector3 pos, global::UnityEngine.Quaternion rot, global::System.Action<global::Effect.EffectInstance> loadcallback, global::UnityEngine.Events.UnityAction<global::Effect.EffectInstance> eff_onFinished) {
        // <PlayEffect>d__162 @01d4e9a0 + DisplayClass162_0 {this, dataIndex +0x18, index +0x1c, pos, rot, parent, loadcallback, eff_onFinished}.
        if (_effectDataArray == null || _effectDataArray[(int)index] == null)
            yield break;

        while (_effectDataArray[(int)index].isLoading)
            yield return null;

        int dataIndex = (int)index;
        if (_effectDataArray[(int)index].isComplete)
        {
            var effect = EffectManager.Instance.Create(_effectDataArray[(int)index].effect, pos, rot, parent);
            loadcallback?.Invoke(effect);
            effect.Play(eff_onFinished);
        }
        else
        {
            var loadParam = EffectManager.Instance.dbEffects.FieldEffectData[dataIndex];
            _effectDataArray[dataIndex].name = Path.GetFileName(loadParam.AssetBundleName);
            _effectDataArray[dataIndex].isComplete = false;
            _effectDataArray[dataIndex].isLoading = true;

            yield return EffectManager.Instance.OpLoad(new EffectManager.LoadParam[] { loadParam }, (effectData, isAllLoaded) =>
            {
                _effectDataArray[dataIndex].isLoading = false;
                _effectDataArray[dataIndex].isComplete = true;
                _effectDataArray[dataIndex].effect = effectData;

                var effect = EffectManager.Instance.Create(_effectDataArray[(int)index].effect, pos, rot, parent);
                loadcallback?.Invoke(effect);
                effect.Play(eff_onFinished);
            });
        }
    }
	private bool ControlPoketch() {
        if (!FlagWork.GetFlag(EvWork.FLAG_INDEX.FE_POKETCH_GET) ||
            FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_FLAG_POKETCH_HOOK) ||
            FlagWork.GetSysFlag(EvWork.SYSFLAG_INDEX.SYS_INPUT_OFF))
            return false;

        // @0179e3d0–0179e430: FieldInput.PushR inlined (shared FieldInput flag 0x4cbb2eb, `tbnz push, #7`).
        if (FieldInput.PushR())
            FieldPoketch.OnPushedAppearButton();
        else
            FieldPoketch.RestorePoketchWindow();

        return FieldPoketch.IsControlPoketch();
    }
