        // mask 0x27 over 445..450 = the three rods and the bicycle, plus ANANUKENOHIMO.
        if ((id == ItemNo.BORONOTURIZAO || id == ItemNo.IITURIZAO || id == ItemNo.SUGOITURIZAO || id == ItemNo.ZITENSYA || id == ItemNo.ANANUKENOHIMO)
