	public bool StartSweetEncount() {
        // @017a358c: CheckIgnoreWeatherSweetEncount inlined (mask 0x3e6fe over weathers 0..17).
        if (CheckIgnoreWeatherSweetEncount(GetBatleWeather()))
        {
            EvDataManager.Instanse.CallLabel("ev_sweet_weather");
            return false;
        }

        var result = FieldEncount.SetSweetEncount();
        if (result == null)
        {
            EvDataManager.Instanse.CallLabel("ev_sweet_no_enc");
            return false;
        }

        GameManager.GetAttribute(EntityManager.activeFieldPlayer.gridPosition, out int code, out int stop, false);
        var attributeTable = GameManager.GetAttributeTable(code);
        var attributeEx = GameManager.GetAttributeEx(EntityManager.activeFieldPlayer.gridPosition, EntityManager.activeFieldPlayer.Height, false);
        int btlBgIndex = AttributeID.MATR_IsWater(attributeTable.Code) ? 1 : 0;

        // byte table 0x3d0d64f: Single / Safari share one arm (isSwim passed as a constant false), Double, MovePoke.
        switch (result.Type)
        {
            case EncountResult.BtlType.Single:
            case EncountResult.BtlType.Safari:
            {
                ResultSetUpWildBattle(result, btlBgIndex, out PokeParty party, out int safariBall);
                EncountTools.SetupBattleWild(PlayerWork.battleSetupParam, party, GameManager.mapInfo[(int)PlayerWork.zoneID].BattleBg[btlBgIndex],
                    attributeEx.AttributeEx, GetBatleWeather(), false, false, TrainerID.NONE, false, safariBall, false, false, null, 0, false);
                break;
            }

            case EncountResult.BtlType.Double:
            {
                ResultSetUpWildBattle(result, btlBgIndex, out PokeParty party, out int safariBall);
                EncountTools.SetupBattleWild(PlayerWork.battleSetupParam, party, GameManager.mapInfo[(int)PlayerWork.zoneID].BattleBg[btlBgIndex],
                    attributeEx.AttributeEx, GetBatleWeather(), PlayerWork.IsFormSwim(), false, result.Partner, false, safariBall, false, false, null, 0, false);
                break;
            }

            case EncountResult.BtlType.MovePoke:
            {
                var movePokeData = default(MV_POKE_DATA);
                EncountDataWork.GetMovePokeData(result.MP_SaveIndex, ref movePokeData);

                ushort sex;
                ushort seikaku;
                switch (result.HatudouTokusei)
                {
                    case TokuseiNo.SINKURO:
                        seikaku = result.FixSeikaku[0] == Seikaku.NUM ? (ushort)0xFFFF : (ushort)result.FixSeikaku[0];
                        sex = 0xFF;
                        break;

                    case TokuseiNo.MEROMEROBODHI:
                        sex = result.FixSex[0] > Sex.FEMALE ? (ushort)0xFF : (ushort)result.FixSex[0];
                        seikaku = 0xFFFF;
                        break;

                    default:
                        seikaku = 0xFFFF;
                        sex = 0xFF;
                        break;
                }

                var pp = EncountTools.CreateFixPokeParam(result.Enemy[0], (ushort)result.Level[0], movePokeData.Hp, sex, seikaku, (Sick)movePokeData.Sick, movePokeData.RndSeed, 3);

                int item1rate;
                switch (result.HatudouTokusei)
                {
                    case TokuseiNo.HUKUGAN:
                    case TokuseiNo.KYOUUN:
                        item1rate = 60;
                        break;

                    default:
                        item1rate = 50;
                        break;
                }
                EncountTools.SetWildPokemonItem(pp, UnityEngine.Random.Range(0, 100), item1rate, 20);

                PlayerWork.MovePokemonIndex = result.MP_SaveIndex;
                var party = new PokeParty();
                party.AddMember(pp);

                ArenaID arenaID = GameManager.mapInfo[(int)PlayerWork.zoneID].BattleBg[btlBgIndex];
                GetLegendPokeEncountInfo(party.GetMemberPointer(0), out string encSeq, ref arenaID, out string bgm, out BattleSetupEffectId setupEffect);
                if (!string.IsNullOrEmpty(encSeq))
                    PreLoadEncEffect(encSeq);

                EncountTools.SetupBattleWild(PlayerWork.battleSetupParam, party, arenaID, attributeEx.AttributeEx, GetBatleWeather(), PlayerWork.IsFormSwim(),
                    false, TrainerID.NONE, false, -1, false, false, bgm, setupEffect, false);
                break;
            }
        }

        if (result.Type != EncountResult.BtlType.MovePoke)
        {
            for (int i = 0; i < PlayerWork.Enc_SV_Data.MovePokeData.Length; i++)
            {
                if (RandomGroupWork.RandomValue(100) < DataManager.FieldCommonParam[(int)ParamIndx.MVPokeEncMoveRate].param)
                    EncountDataWork.MovePoke_RandomZone(i);
            }
        }

        EncountStart(EncountFadeType.Normal);
        return true;
    }
