	private void GetLegendPokeEncountInfo(global::Pml.PokePara.PokemonParam param, out string encSec, ref global::ArenaID arenaID, out string bgm, out global::BattleSetupEffectId setupEffect) {
        encSec = null;
        bgm = null;
        setupEffect = (BattleSetupEffectId)0;
        global::XLSXContent.FieldEncountTable.Sheetlegendpoke data = GetFieldEncountTableLegendPoke(param.GetMonsNo(), param.GetFormNo());
        if (data == null)
            return;

        if (data.isFixedEncSeq)
            encSec = data.encSeq;

        if (data.isFixedBGM)
            bgm = data.bgmEvent;

        if (data.isFixedBtlBg)
            arenaID = data.btlBg;

        if (data.isFixedSetupEffect)
            setupEffect = data.setupEffect;

        if (data.waza1 >= 0)
            param.SetWaza(0, (WazaNo)data.waza1);

        if (data.waza2 >= 0)
            param.SetWaza(1, (WazaNo)data.waza2);

        if (data.waza3 >= 0)
            param.SetWaza(2, (WazaNo)data.waza3);

        if (data.waza4 >= 0)
            param.SetWaza(3, (WazaNo)data.waza4);
    }
	private static global::XLSXContent.FieldEncountTable.Sheetlegendpoke GetFieldEncountTableLegendPoke(global::Pml.MonsNo monsNo, ushort formNo) {
        for (int i = 0; i < GameManager.fieldEncountTable.legendpoke.Length; i++)
        {
            global::XLSXContent.FieldEncountTable.Sheetlegendpoke data = GameManager.fieldEncountTable.legendpoke[i];
            if (data.monsNo == monsNo && (data.formNo == -1 || data.formNo == formNo))
                return data;
        }

        return null;
    }
	public bool IsEnableSave(bool isIgnoreGround = false) {
        FieldPlayerEntity player = EntityManager.activeFieldPlayer;
        if (IsNoEntry(player.gridPosition, player.worldPosition))
            return false;

        if (IsNoEntrySea(player.gridPosition, player.worldPosition))
            return false;

        if (!isIgnoreGround && !CollisionUtility.IsCollideGround(player.worldPosition, 1f, Layer.Ground))
            return false;

        return true;
    }
	public bool IsNoEntry(global::UnityEngine.Vector2Int gridPos, global::UnityEngine.Vector3 worldPos) {
        GameManager.GetAttribute(gridPos, out int code, out int stop, false);
        if (stop == 0x80)
            return true;

        var attributeEx = GameManager.GetAttributeEx(gridPos, worldPos.y, false);
        return attributeEx != null && attributeEx.Code == 0;
    }
	public bool IsNoEntrySea(global::UnityEngine.Vector2Int gridPos, global::UnityEngine.Vector3 worldPos) {
        // @017a48e0: a 4-way flood fill over the attribute-ex matrix from the player's sea tile (code 0x14); any reachable tile with another non-zero
        // height attribute means the sea is open (false); an enclosed sea pocket is "no entry" (true). The first GetAttributeEx result is not null-tested.
        var attributeEx = GameManager.GetAttributeEx(gridPos, worldPos.y, false);
        if (attributeEx.Code != 0x14)
            return false;

        if (PlayerWork.zoneID == ZoneID.UNKNOWN)
            return false;

        global::XLSXContent.AttributeMatrix matrix = GameManager.GetMapAttributeExMattrix();
        if (matrix == null)
            return false;

        var visited = new Dictionary<int, List<int>>();
        var queue = new Queue<Vector2Int>();
        var directions = new List<Vector2Int>();
        directions.Add(new Vector2Int(-1, 0));
        directions.Add(new Vector2Int(1, 0));
        directions.Add(new Vector2Int(0, -1));
        directions.Add(new Vector2Int(0, 1));

        queue.Enqueue(new Vector2Int(gridPos.x, gridPos.y));
        visited.Add(gridPos.x, new List<int> { gridPos.y });

        while (queue.Count > 0)
        {
            var current = queue.Dequeue();
            for (int i = 0; i < directions.Count; i++)
            {
                var next = new Vector2Int(current.x + directions[i].x, current.y + directions[i].y);
                int blockX = next.x % 32;
                int blockY = next.y % 32;
                if (blockX < 0 || blockY < 0)
                    continue;

                global::XLSXContent.AttributeBlock block = matrix[next.x / 32, next.y / 32];
                if (block == null || block.Attributes == null)
                    continue;

                int height = GameManager.HeightAttribute(block[blockX, blockY], worldPos.y);
                if (height == 0)
                    continue;

                if (height != 0x14)
                    return false;

                if (visited.ContainsKey(next.x) && visited[next.x].Contains(next.y))
                    continue;

                queue.Enqueue(next);
                if (!visited.ContainsKey(next.x))
                    visited.Add(next.x, new List<int>());

                visited[next.x].Add(next.y);
            }
        }

        return true;
    }
